-- ============================================================================
-- 0013_descriptions_and_families.sql
--
-- Dua pengisian besar supaya knowledge base tidak lagi berlubang:
--
--   1. 406 deskripsi profesi yang masih berteks O*NET diganti
--      dengan teks Indonesia.
--   2. 61 rumpun tambahan supaya seluruh 477 profesi punya rumpun,
--      bukan cuma 21 yang dikurasi di 0011.
--
-- SEMUA HASIL GENERATE, BUKAN TULISAN MANUSIA.
--
-- Deskripsinya tidak diterjemahkan kalimat per kalimat dari O*NET, melainkan
-- dirakit dari data yang sudah berbahasa Indonesia: capaian inti (IWA yang
-- sudah diterjemahkan di 0007), Activity DNA, Environment DNA, dan jenjang
-- pendidikan. Konsekuensinya seragam dan agak formulaik — tapi lengkap untuk
-- semua profesi, dan polanya bisa diperbaiki serentak dari satu tempat
-- (supabase/roadmap/gen_desc_fam.py) alih-alih disunting 400 kali.
--
-- Nama rumpun otomatis diambil dari profesi paling representatif di grupnya.
-- Ini yang paling kasar di seluruh migrasi ini: "Kelompok profesi serumpun
-- menurut O*NET" bukan nama yang enak dibaca siswa. Semuanya ditandai
-- is_curated = false dan menunggu penamaan manusia; yang 21 dari 0011 tidak
-- disentuh.
--
-- Jalankan setelah 0012. Aman diulang.
-- ============================================================================

begin;

alter table public.careers add column if not exists description_source text;
alter table public.career_families add column if not exists is_curated boolean not null default false;

update public.career_families set is_curated = true
where code in ('SALES_RITEL','SALES_LAPANGAN','SALES_SUPERVISI','SALES_B2B',
               'SALES_LISENSI','MARKETING','VISUAL_MERCH');

