do $$
declare n int;
begin
  select count(*) into n from public.careers where is_active and family_code is null;
  if n > 0 then raise exception '% profesi aktif masih tanpa rumpun', n; end if;
  select count(*) into n from public.careers where is_active and career_description is null;
  if n > 0 then raise exception '% profesi aktif tanpa deskripsi', n; end if;
end $$;

